-- Test-only fixture, matched to live read-only metadata. Not an application migration.

CREATE TABLE applications (
 id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 code varchar(50) NOT NULL UNIQUE,
 name varchar(100) NOT NULL,
 status varchar(16) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISABLED')),
 is_system boolean NOT NULL DEFAULT false,
 CHECK (code ~ '^[a-z][a-z0-9_]*$')
);

CREATE SEQUENCE role_numeric_code_seq AS integer MINVALUE 1;

CREATE TABLE auth (
 "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "email" character varying(100) NOT NULL,
 "password" character varying(150) NOT NULL,
 "created_at" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
 "updated_at" timestamp without time zone,
 "deleted_at" timestamp without time zone,
 "status" character varying(16) DEFAULT 'PENDING'::character varying NOT NULL,
 "auth_version" bigint DEFAULT 1 NOT NULL,
 "must_change_password" boolean DEFAULT false NOT NULL,
 "version" bigint DEFAULT 1 NOT NULL,
 "password_changed_at" timestamp with time zone,
 CONSTRAINT "PK_auth" PRIMARY KEY (id),
 CONSTRAINT "auth_email_normalized_ck" CHECK ((((email)::text = lower(btrim((email)::text))) AND ((email)::text <> ''::text))),
 CONSTRAINT "auth_status_ck" CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'ACTIVE'::character varying, 'SUSPENDED'::character varying, 'DEACTIVATED'::character varying])::text[]))),
 CONSTRAINT "auth_version_ck" CHECK (((version >= 1) AND (auth_version >= 1))),
 CONSTRAINT "unique_key_email" UNIQUE (email)
);

CREATE TABLE profile (
 "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "user_id" integer NOT NULL,
 "name" character varying(100),
 "address" character varying(250),
 "phone" character varying(20),
 CONSTRAINT "fk_user_id_id" FOREIGN KEY (user_id) REFERENCES auth(id) ON DELETE RESTRICT,
 CONSTRAINT "profile_pk" PRIMARY KEY (id),
 CONSTRAINT "profile_user_id_uq" UNIQUE (user_id)
);

CREATE TABLE role (
 "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "role_name" character varying(50) NOT NULL,
 "role_code" integer DEFAULT nextval('role_numeric_code_seq'::regclass) NOT NULL,
 "role_description" character varying(100),
 "application_id" integer NOT NULL,
 "code" character varying(100) NOT NULL,
 "status" character varying(16) DEFAULT 'ACTIVE'::character varying NOT NULL,
 "is_system" boolean DEFAULT false NOT NULL,
 "version" bigint DEFAULT 1 NOT NULL,
 "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
 "updated_at" timestamp with time zone,
 CONSTRAINT "role_application_fk" FOREIGN KEY (application_id) REFERENCES applications(id) ON DELETE RESTRICT,
 CONSTRAINT "role_code_string_ck" CHECK (((code)::text ~ '^[a-z][a-z0-9_]*[.][a-z][a-z0-9_]*$'::text)),
 CONSTRAINT "role_code_string_uq" UNIQUE (code),
 CONSTRAINT "role_status_ck" CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'DISABLED'::character varying])::text[]))),
 CONSTRAINT "role_version_ck" CHECK ((version >= 1)),
 CONSTRAINT "uq_role_code" UNIQUE (role_code),
 CONSTRAINT "user_id_pkey" PRIMARY KEY (id)
);

CREATE TABLE user_role (
 "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "user_id" integer NOT NULL,
 "role_id" integer NOT NULL,
 "status" character varying(16) DEFAULT 'ACTIVE'::character varying NOT NULL,
 "granted_by" integer,
 "granted_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
 "revoked_by" integer,
 "revoked_at" timestamp with time zone,
 "revoke_reason" character varying(500),
 CONSTRAINT "PK_user_role" PRIMARY KEY (id),
 CONSTRAINT "role_fk" FOREIGN KEY (role_id) REFERENCES role(id),
 CONSTRAINT "user_fk" FOREIGN KEY (user_id) REFERENCES auth(id),
 CONSTRAINT "user_role_granted_by_fk" FOREIGN KEY (granted_by) REFERENCES auth(id) ON DELETE RESTRICT,
 CONSTRAINT "user_role_pair_uq" UNIQUE (user_id, role_id),
 CONSTRAINT "user_role_revocation_ck" CHECK (((((status)::text = 'ACTIVE'::text) AND (revoked_at IS NULL)) OR (((status)::text = 'REVOKED'::text) AND (revoked_at IS NOT NULL) AND (revoke_reason IS NOT NULL) AND ((char_length(btrim((revoke_reason)::text)) >= 3) AND (char_length(btrim((revoke_reason)::text)) <= 500))))),
 CONSTRAINT "user_role_revoked_by_fk" FOREIGN KEY (revoked_by) REFERENCES auth(id) ON DELETE RESTRICT,
 CONSTRAINT "user_role_status_ck" CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'REVOKED'::character varying])::text[])))
);

CREATE TABLE audit_logs (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "actor_user_id" integer,
 "actor_service" character varying(100),
 "action" character varying(100) NOT NULL,
 "target_type" character varying(50) NOT NULL,
 "target_id" character varying(100) NOT NULL,
 "safe_before" jsonb,
 "safe_after" jsonb,
 "reason" character varying(500),
 "request_id" character varying(100),
 "trace_id" character varying(100),
 "occurred_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
 CONSTRAINT "audit_actor_ck" CHECK (((actor_user_id IS NOT NULL) OR (NULLIF(btrim((actor_service)::text), ''::text) IS NOT NULL))),
 CONSTRAINT "audit_logs_actor_user_id_fkey" FOREIGN KEY (actor_user_id) REFERENCES auth(id) ON DELETE RESTRICT,
 CONSTRAINT "audit_logs_pkey" PRIMARY KEY (id)
);

CREATE TABLE outbox_events (
 "event_id" uuid NOT NULL,
 "event_type" character varying(100) NOT NULL,
 "schema_version" integer DEFAULT 1 NOT NULL,
 "aggregate_type" character varying(50) NOT NULL,
 "aggregate_id" character varying(100) NOT NULL,
 "aggregate_version" bigint NOT NULL,
 "payload" jsonb NOT NULL,
 "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
 "published_at" timestamp with time zone,
 "attempts" integer DEFAULT 0 NOT NULL,
 "next_attempt_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
 "lease_owner" character varying(100),
 "lease_expires_at" timestamp with time zone,
 "last_error_code" character varying(100),
 CONSTRAINT "outbox_attempts_ck" CHECK ((attempts >= 0)),
 CONSTRAINT "outbox_events_pkey" PRIMARY KEY (event_id),
 CONSTRAINT "outbox_lease_ck" CHECK (((lease_owner IS NULL) = (lease_expires_at IS NULL))),
 CONSTRAINT "outbox_version_ck" CHECK (((aggregate_version >= 1) AND (schema_version >= 1)))
);

CREATE TABLE idempotency_records (
 "actor_id" integer NOT NULL,
 "method" character varying(100) NOT NULL,
 "route_scope" character varying(300) NOT NULL,
 "key" character varying(200) NOT NULL,
 "request_hash" bytea NOT NULL,
 "safe_response" jsonb NOT NULL,
 "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
 "expires_at" timestamp with time zone NOT NULL,
 CONSTRAINT "idempotency_expiry_ck" CHECK ((expires_at > created_at)),
 CONSTRAINT "idempotency_hash_ck" CHECK ((octet_length(request_hash) > 0)),
 CONSTRAINT "idempotency_key_ck" CHECK ((btrim((key)::text) <> ''::text)),
 CONSTRAINT "idempotency_records_actor_id_fkey" FOREIGN KEY (actor_id) REFERENCES auth(id) ON DELETE RESTRICT,
 CONSTRAINT "idempotency_records_pkey" PRIMARY KEY (actor_id, method, route_scope, key)
);

CREATE INDEX audit_actor_time_idx ON audit_logs USING btree (actor_user_id, occurred_at DESC, id DESC);

CREATE INDEX audit_target_time_idx ON audit_logs USING btree (target_type, target_id, occurred_at DESC, id DESC);

CREATE INDEX audit_time_idx ON audit_logs USING btree (occurred_at DESC, id DESC);

CREATE INDEX auth_status_id_idx ON auth USING btree (status, id);

CREATE INDEX idx_id_email ON auth USING btree (id DESC, email DESC);

CREATE INDEX idempotency_expiry_idx ON idempotency_records USING btree (expires_at);

CREATE INDEX outbox_pending_idx ON outbox_events USING btree (next_attempt_at, created_at, event_id) WHERE (published_at IS NULL);

CREATE INDEX role_application_status_id_idx ON role USING btree (application_id, status, id);

CREATE INDEX user_role_role_status_idx ON user_role USING btree (role_id, status, user_id);

CREATE INDEX user_role_user_status_idx ON user_role USING btree (user_id, status, role_id);

